// Moore FSM, one input, one output, four states. Synchronous reset to
// state A.
module TopModule(input  clk, input reset, input in, output reg out);
  reg [1:0] state, next_state;
  always @(*) begin
    case (state)
      2'b00: begin out=1'b0; next_state=(in ? 2'b01 : 2'b00); end
      2'b01: begin out=1'b0; next_state=(in ? 2'b10 : 2'b01); end
      2'b10: begin out=1'b1; next_state=(in ? 2'b00 : 2'b11); end
      2'b11: begin out=1'b0; next_state=(in ? 2'b10 : 2'b01); end
    endcase
  end
  always @(posedge clk) begin
    if (reset) state <= 2'b00;
    else state <= next_state;
  end
endmodule

