// One-bit Moore state machine
module TopModule(
    input  clk,
    input  reset,
    input  in,
    output reg out
);
    // State register
    reg [1:0] state;
    // Next state combinational logic
    wire [1:0] next_state = (in) ? {state[0], 1'b1} : {state[0], 1'b0};
    // Output combinational logic
    always @(*) begin
        case (state)
            2'b00: out = 1'b0;
            2'b01: out = 1'b0;
            2'b10: out = 1'b0;
            2'b11: out = 1'b1;
        endcase
    end
    // State transition
    always @(posedge clk) begin
        if (reset) state <= 2'b00;
        else state <= next_state;
    end
endmodule

