// Moore state machine, synchronous reset, one input, one output, four
// states.
module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);
    reg [1:0] state, next_state;
    reg [1:0] next_state_table [0:3];
    reg [1:0] state_table [0:3];
    wire o;
    assign o = state_table[state][1];
    always @* begin
        next_state = next_state_table[state][in];
    end
    always @(posedge clk) begin
        if (reset) state <= 2'd0;
        else state <= next_state;
    end
    always @* begin
        state_table[0][0] = 2'd0; state_table[0][1] = 1'b0;
        state_table[1][0] = 2'd1; state_table[1][1] = 1'b0;
        state_table[2][0] = 2'd2; state_table[2][1] = 1'b0;
        state_table[3][0] = 2'd3; state_table[3][1] = 1'b1;
        next_state_table[0][0] = 2'd0; next_state_table[0][1] = 2'd1;
        next_state_table[1][0] = 2'd2; next_state_table[1][1] = 2'd1;
        next_state_table[2][0] = 2'd0; next_state_table[2][1] = 2'd3;
        next_state_table[3][0] = 2'd2; next_state_table[3][1] = 2'd1;
    end
    assign out = o;
endmodule

